Straight-line example: read, trim, then log progress and return in the same block:

{
  "entry_block_ref": "read_input",
  "declared_context_keys": [
    "user_input"
  ],
  "blocks": [
    {
      "block_ref": "read_input",
      "block_name": "Read the user's input message",
      "data_source_kind": "context",
      "instructions": [
        {
          "instruction_ref": "read",
          "opcode": "read_user_message",
          "inputs": [
            {
              "type": "context_key",
              "identifier": "user_input"
            }
          ],
          "outputs": [
            {
              "type": "result",
              "identifier": "raw_message"
            }
          ]
        },
        {
          "instruction_ref": "go_normalize",
          "opcode": "dispatch"
        }
      ]
    },
    {
      "block_ref": "normalize",
      "block_name": "Remove leading and trailing whitespace from the message",
      "data_source_kind": null,
      "instructions": [
        {
          "instruction_ref": "normalize_message",
          "opcode": "trim_message_whitespace",
          "inputs": [
            {
              "type": "result",
              "identifier": "raw_message"
            }
          ],
          "outputs": [
            {
              "type": "result",
              "identifier": "normalized_message"
            }
          ]
        },
        {
          "instruction_ref": "go_record",
          "opcode": "dispatch"
        }
      ]
    },
    {
      "block_ref": "record",
      "block_name": "Record progress and return the normalized message",
      "data_source_kind": null,
      "instructions": [
        {
          "instruction_ref": "record_progress",
          "opcode": "log_progress",
          "inputs": [
            {
              "type": "literal",
              "literal_value": "ready"
            }
          ]
        },
        {
          "instruction_ref": "return_message",
          "opcode": "return",
          "inputs": [
            {
              "type": "result",
              "identifier": "normalized_message"
            }
          ]
        }
      ]
    }
  ],
  "edges": [
    {
      "source_block_ref": "read_input",
      "target_block_ref": "normalize"
    },
    {
      "source_block_ref": "normalize",
      "target_block_ref": "record"
    }
  ],
  "diagnostics": []
}

